<?php
require_once __DIR__.'/includes/functions.php';$order=null;$items=[];$error='';
if($_SERVER['REQUEST_METHOD']==='POST'){verify_csrf();$ref=trim($_POST['order_number']??'');$phone=preg_replace('/\D+/','',$_POST['phone']??'');if($ref&&$phone){$s=db()->prepare('SELECT o.*,c.full_name,c.phone,c.address FROM orders o JOIN customers c ON c.id=o.customer_id WHERE o.order_number=?');$s->execute([$ref]);$candidate=$s->fetch();if($candidate&&hash_equals(preg_replace('/\D+/','',$candidate['phone']),$phone)){$order=$candidate;$s=db()->prepare('SELECT product_name,quantity FROM order_items WHERE order_id=?');$s->execute([$order['id']]);$items=$s->fetchAll();}else $error='We could not find an order with those details.';}else $error='Enter your order reference and checkout phone number.';}
$page_title='Track an order';require 'includes/header.php';?><section class="section"><div class="container auth-card"><p class="eyebrow">Delivery updates</p><h1>Track your order</h1><p>Enter your order reference and the phone number used at checkout.</p><form method="post"><input type="hidden" name="csrf" value="<?=csrf_token()?>"><label>Order reference<input required name="order_number" value="<?=e($_POST['order_number']??'')?>"></label><label>Checkout phone<input required name="phone" autocomplete="tel"></label><button class="button primary">Find order</button></form><?php if($error):?><p class="notice notice-error"><?=e($error)?></p><?php endif;if($order):$stages=['Pending','Processing','Shipped','Out for Delivery','Delivered'];$idx=array_search($order['status'],$stages,true);if($order['status']==='Confirmed'||$order['status']==='Ready for Delivery')$idx=1;if($order['status']==='Completed')$idx=4;?><div class="account-order"><h2><?=e($order['order_number'])?></h2><p><?=e($order['status'])?> · <?=money($order['total'])?></p><p><?=e($order['address'])?></p><h3>Items</h3><ul><?php foreach($items as $item):?><li><?=e($item['product_name'])?> × <?=$item['quantity']?></li><?php endforeach?></ul><?php if($idx!==false):?><div class="order-progress"><span style="--progress:<?=((int)$idx/4)*100?>%"></span></div><small>Placed · Processing · Shipped · Out for delivery · Delivered</small><?php endif?></div><?php endif?></div></section><?php require 'includes/footer.php';
